export type ResourceSection = { heading: string; body: string };

// Article-specific supporting sections expand each resource into a practical long-form guide.
export const resourceDetails: Record<string, ResourceSection[]> = {
  "lost-car-keys-benoni": [
    { heading: "Start by checking the immediate situation", body: "Before arranging replacement, take a moment to establish where the key could be and whether the vehicle is secure. Check the usual places, bags and clothing, then confirm that the key is not still inside the car. If you are at a workplace, shopping centre or another managed site, ask whether a lost-property desk has received it. If the key may have been taken with your address or vehicle details, mention that when you call because the security implications may differ from a simple misplacement. Avoid trying to force a door or operating unfamiliar tools around the lock. That can damage trim, wiring or the locking mechanism and may make a straightforward key problem more expensive to resolve. If the car is parked somewhere unsafe, explain the location and circumstances when requesting assistance so the next step can be considered sensibly." },
    { heading: "Collect the details that identify the vehicle", body: "Write down the make, model, year and, if available, the registration or VIN. The VIN is commonly found on vehicle documentation and in designated places on the car, but you do not need to send it to an unverified person. Tell the locksmith whether the vehicle uses a conventional blade, a remote-head key, a proximity fob or a start button if you know. Describe whether all keys are missing or a spare remains, and mention any warning lights or recent key problems. These details help a technician judge whether the vehicle may be supported and what equipment could be needed. They do not guarantee that a particular key can be made; some model years have different systems even when the vehicle name is the same. Travokeys is based in Crystal Park, Benoni, and can discuss supported vehicles by phone." },
    { heading: "Be ready to confirm your authority", body: "An automotive key can unlock and start a vehicle, so a locksmith may ask for reasonable proof that you own the car or have permission to request the work. Ask in advance what documents are acceptable in your circumstances. Depending on the situation, this may involve identification and vehicle paperwork, but do not assume one document will always be enough. If the vehicle belongs to a family member, employer or customer, explain who is authorising the job and have that person available if requested. Share only the information needed to arrange the service, and use a contact channel you have independently checked. These checks are a normal part of responsible vehicle-security work; they help protect owners as well as the technician. If your documents are locked inside the vehicle, say so on the call and ask how authorisation can be established before any work starts." },
    { heading: "Ask what replacement involves before approving work", body: "A replacement may involve cutting a blade, programming a transponder, pairing a remote, or a combination of those tasks. The right solution depends on the vehicle and the condition of its security system. Ask whether the quoted work includes the key, cutting, coding, testing and any call-out or travel charge. If all keys are lost, the process can differ from adding a spare while one working key is available. A phone estimate may need to be confirmed after the vehicle or key system is identified. Request an explanation of any additional work before it is carried out, and make sure you understand what the replacement will and will not do. Do not rely on a guaranteed price or completion time from a generic online listing that has not asked about your particular vehicle." },
    { heading: "Consider security if a key may have been stolen", body: "If you think the key was stolen rather than misplaced, the question is not only how to obtain another key. Consider whether the key was attached to anything identifying your home or the vehicle’s location, and tell the locksmith or relevant vehicle professional about that context. Some vehicles offer ways to change which keys the system accepts, while others require a different security assessment. The available option depends on the make, model, year and security configuration. Do not assume that cutting a second blade alone disables a missing electronic key. Ask a qualified provider to explain what can be checked or changed for your specific car. If there is an immediate safety concern, contact the appropriate local authorities or property security team as well as arranging vehicle assistance." },
    { heading: "Make the next lost-key event less disruptive", body: "Once access is restored, ask whether a spare can be made for your vehicle while the system is already being assessed. Keep it in a secure place that is separate from your everyday key, and avoid leaving it inside the vehicle. Consider a labelled key pouch or a trusted person who can store it without displaying your registration or address. If a key is damaged or intermittently recognised, address the issue before it becomes your only way to use the car. Record the vehicle details and the locksmith’s confirmed instructions in a safe place. These small preparations cannot prevent every loss, but they can make the next conversation faster and reduce the chance that a single misplaced key leaves you without options." },
  ],
  "spare-car-key": [
    { heading: "Why a spare is useful before there is an emergency", body: "A spare key gives you another option when the everyday key is misplaced, damaged or unavailable. It can also help when more than one authorised driver regularly uses the vehicle. Arranging a spare while a working key is available may be simpler on some vehicles than replacing every missing key later, although the exact process varies. There is no universal price or programming method: the key type, vehicle security system and availability of compatible parts all matter. Think of a spare as part of practical vehicle preparedness, like keeping important documents accessible. It is most valuable when it has been tested, stored securely and is genuinely available to the people who may need it. A spare left in the car defeats much of its purpose and may create a security risk." },
    { heading: "Choose a key that matches the functions you use", body: "A vehicle key may combine a physical blade, remote locking buttons, a transponder and proximity features. A replacement spare might support every original function, or it may be a simpler option depending on the vehicle and the parts available. Explain which features matter to you: starting the engine, remote locking, boot release or keyless entry. Ask the provider to distinguish between a blade that operates a lock and a coded key that the immobiliser recognises. A key that looks similar is not necessarily compatible. The correct model or part reference may depend on the year and vehicle specification. Confirm what will be supplied and what will be tested before authorising the job, especially if the spare is intended for another regular driver." },
    { heading: "Understand cutting and coding", body: "Cutting shapes the metal blade so it matches the relevant vehicle lock. Coding or programming concerns the electronic identification the vehicle expects from a transponder or remote. Some vehicle keys require both operations; others use different arrangements. Remote buttons can sometimes work independently from the immobiliser function, so a key may lock the doors but still fail to start the engine, or start the car while the remote buttons do not work. Ask the locksmith which functions are included in the spare and how they will verify them. A clear explanation can help prevent confusion after the appointment. If the vehicle has an unusual or aftermarket security system, mention it before booking because it may affect compatibility and the work required." },
    { heading: "Plan how the spare will be stored", body: "Store the spare somewhere secure, dry and separate from your normal key. If a household member or colleague may need it, make sure they know where it is and how to use it. Avoid attaching a tag that reveals your home address, vehicle registration or parking location if the key is lost. Keep the key away from strong impacts and liquids, and replace a remote battery when it shows signs of weakening rather than waiting for complete failure. If the spare is a proximity fob, follow the vehicle maker’s guidance about storage and battery care. A spare is only useful if it is accessible during a real problem, so balance security with a sensible plan for authorised drivers." },
    { heading: "Test the spare before you rely on it", body: "When the spare is ready, test the functions that were agreed: turning the blade if applicable, starting the vehicle, remote locking and any other included feature. Perform the checks with the vehicle in a safe, stationary location and follow the owner’s manual. If a button or feature does not work, raise it immediately while the locksmith can still inspect the key and vehicle. Do not assume that a new key is faulty because one feature behaves differently; first clarify which functions the spare was designed to support. Keep any receipt or written description of the work. This gives both you and the service provider a clear record if a question arises later." },
    { heading: "When to ask for a spare", body: "Consider arranging a spare after buying a used vehicle, when a second authorised driver starts using the car, or when you notice that only one key remains. It is also a useful time to ask about the condition of the existing key casing, buttons and remote battery. If your current key has an intermittent fault, describe the symptoms and have it assessed rather than duplicating an unreliable key without explanation. Travokeys can check whether your vehicle is supported for key cutting and coding. Call with the make, model and year, and ask for the expected scope and price before confirming. Preparing early helps you make an informed decision without the pressure of a car that cannot be accessed." },
  ],
  "car-key-cutting-and-coding": [
    { heading: "The physical key and electronic key are different parts", body: "The familiar metal blade is only one part of many modern vehicle keys. It needs the correct cut to operate a mechanical lock or ignition where one is fitted. Separately, a transponder or other electronic component may need to be recognised by the vehicle’s immobiliser. Remote buttons can be a third function, controlling locks or other features. These systems can be combined in one shell, but they do not all do the same job. Understanding the distinction helps explain why a key may turn but not start the car, or why a remote may fail while the blade still works. When asking for a replacement, describe every symptom rather than simply asking for a copy of the visible shape." },
    { heading: "What information helps identify the right key", body: "Provide the vehicle make, model, year and, if known, trim or market specification. Tell the locksmith whether you have a working key, a damaged key or no keys at all. A photograph can sometimes help with an initial conversation, but it may not show the electronic part number or prove compatibility. The vehicle identification number may be useful in some cases, but share it only with a service provider you trust and only through an appropriate channel. Mention any previous replacement keys, aftermarket alarms or modifications that could affect the immobiliser. This information helps determine whether the job is likely to be supported and what additional checks may be needed. The final assessment can still depend on seeing the vehicle and key system." },
    { heading: "How the work is generally approached", body: "A locksmith first establishes what type of key and security system the vehicle uses and confirms that the customer is authorised to request the work. The blade, if present, is cut to suit the required lock. Electronic coding is then assessed separately and completed only when the vehicle and key are compatible with the available equipment. The locksmith should explain the planned steps and ask before doing additional work outside the agreed scope. Testing should cover the functions that were quoted, such as starting, remote locking or other included features. The precise sequence varies by make and model, so an online description of one vehicle’s procedure should not be treated as a guide for a different car." },
    { heading: "Why compatibility matters", body: "Two keys that look alike can contain different electronics or use different frequencies, transponder types or security generations. A key that is physically cut correctly may still not be recognised by a vehicle. Conversely, a compatible electronic key may need a correctly cut blade for mechanical access. Model-year changes, import specifications and replacement modules can all affect what is suitable. Ask the service provider to confirm the key type and functions included before paying for a part. If an exact match is unavailable, ask what alternatives exist and what functionality might differ. A careful compatibility check reduces wasted parts and helps set realistic expectations before work begins." },
    { heading: "Common misunderstandings", body: "A copied blade is not necessarily a complete modern car key. Replacing a remote battery does not normally create a new transponder key, and a remote that locks the doors does not automatically prove that the immobiliser will accept it. Likewise, a diagnostic fault related to key recognition does not by itself confirm that the key is the only cause. Vehicle wiring, receiver components or security modules can also be relevant. Ask for the distinction between cutting, coding, remote pairing and diagnosis in plain language. If the service provider proposes more than one of these, request a clear explanation of why each step is needed and what the price covers." },
    { heading: "Prepare for a smooth appointment", body: "Have the vehicle accessible and bring any keys or remotes you still have, even if they are damaged or unreliable. Gather documentation that may help show you are authorised to request the work, and ask in advance what is accepted. Note the vehicle’s symptoms and when they happen. If you are arranging service for someone else, ensure the owner can confirm permission if needed. Before authorising the job, confirm the estimated price, any call-out fee, the included key functions and how the finished work will be tested. Travokeys offers key cutting and coding for supported vehicles in Benoni; call with your vehicle details to check availability." },
  ],
  "transponder-key-basics": [
    { heading: "What the transponder does", body: "A transponder is a small electronic identifier associated with many vehicle keys. When the key is used, the vehicle’s immobiliser checks for a recognised signal or code before allowing the engine to start. The exact technology differs across manufacturers and model years. The transponder may sit inside a remote-head key, a separate fob or another design. Its purpose is distinct from the metal blade, which operates a mechanical lock, and distinct from remote buttons, which commonly operate central locking. This is why a key can appear intact yet fail to start a vehicle, or why remote locking can work while the engine will not start. A technician assesses the key and vehicle system together rather than relying only on appearance." },
    { heading: "Symptoms can point to several possible causes", body: "A car that cranks but does not start, a security light that behaves differently, or a message saying the key is not detected may lead an owner to suspect the transponder. Those observations are useful, but they do not prove that the key chip has failed. The vehicle’s receiver, wiring, immobiliser module, battery condition or another system fault may produce similar symptoms. If the issue is intermittent, note when it happens and whether it follows a drop, water exposure or a battery change. Mention whether another authorised key behaves differently. Avoid repeatedly attempting random resets, because the correct procedure varies by vehicle and may create additional issues." },
    { heading: "Replacement keys need the right electronic match", body: "A replacement key must be suitable for the vehicle’s system and then configured where required. A visually similar transponder is not necessarily compatible. The vehicle make, model, year and specification help narrow down the likely key family, but part identification may still be required. If you have a working key, tell the locksmith; adding a spare can involve a different process from replacing every missing key. Ask whether the quote includes the blade, transponder, coding and any remote functions. Confirm how the finished key will be checked. An explanation of these items makes it easier to understand what is being supplied and what to do if a particular feature behaves differently." },
    { heading: "What to do if the key is not recognised", body: "Start with the owner’s manual and look for the vehicle’s official guidance about key warnings or starting issues. If there is a spare key, you may compare whether it produces the same result, while keeping the vehicle in a safe place. Note dashboard messages and whether the engine turns over. Do not dismantle the key or attempt to bypass the immobiliser. Vehicle anti-theft systems are designed to restrict access, and bypass attempts can damage components or create legal and security concerns. Share the symptoms and vehicle details with an automotive locksmith or appropriate vehicle specialist so they can assess the key and car without assuming a single cause." },
    { heading: "Programming is vehicle-specific", body: "The steps and equipment used to pair a transponder are not universal. Some vehicles require a specific diagnostic process, and others have security procedures that depend on the manufacturer or market. Existing keys, replacement modules or aftermarket systems may change the assessment. Do not rely on generic video instructions that claim one sequence works for every car. A professional should first confirm the vehicle and explain whether the requested key can be programmed with the available method. If programming is not possible or a different fault is found, ask what alternatives or next steps are available before approving extra work." },
    { heading: "Keeping transponder keys in good condition", body: "Avoid dropping the key repeatedly, exposing it to moisture or storing it where it can be crushed. If the key casing is cracked, a suitable casing replacement may help protect the internals, provided the electronic components remain usable and compatible. Remote battery symptoms can affect buttons, although the transponder and remote may not share identical power arrangements. Keep a spare in a secure, dry place and test it occasionally. If the vehicle begins recognising a key inconsistently, arrange an assessment before the issue leaves you without a working option. Travokeys can discuss supported key services in Benoni when you provide your vehicle make, model and year." },
  ],
  "remote-stopped-working": [
    { heading: "Notice exactly what has stopped working", body: "A car remote can control several functions, and identifying which ones still work is a useful first step. Do the lock and unlock buttons fail, while the key still starts the car? Does one button respond but another not? Does the remote work only very close to the vehicle? Note whether a spare remote behaves differently. This information helps distinguish a battery or button issue from a broader vehicle-side fault, although it does not confirm a diagnosis by itself. Also mention recent events such as a drop, water exposure, casing damage or a battery replacement. Clear observations are more useful than repeatedly pressing every button and hoping the problem resolves." },
    { heading: "A weak battery is only one possibility", body: "Remote batteries lose charge over time, so reduced range or intermittent button response can be consistent with a weakening battery. But similar symptoms may come from worn rubber buttons, corroded contacts, damaged circuit components, a poor battery connection or interference. A vehicle receiver or locking-system issue can also affect more than one remote. Before replacing parts, ask a technician to inspect the remote type and reported symptoms. If a suitable battery change does not restore the expected operation, do not keep buying batteries without checking for another cause. The vehicle’s manual may describe a manufacturer-approved resynchronisation step, but the method differs by model." },
    { heading: "Treat moisture and impact damage carefully", body: "A remote that has been dropped or exposed to liquid can suffer damage even if the outside looks normal. Do not heat it, place it in an oven, or use household cleaners on the circuit board. If the casing is wet, avoid repeatedly pressing the buttons, because that can worsen an electrical problem. A locksmith or electronics technician can inspect whether cleaning, a casing repair or a replacement remote is appropriate. Share what happened and when; this helps the assessment. A cracked case can also allow dirt and moisture inside, so ask whether a casing replacement is suitable if the remote still works." },
    { heading: "When a button or casing repair may help", body: "If one button feels soft, sticks or has lost its rubber cover while the others operate normally, the button pad or casing may be worn. Replacing the rubber button cover is different from repairing the remote’s electronics. A new case must match the key’s shape, button arrangement and internal board. A poor fit can leave buttons misaligned or the board inadequately protected. The technician should inspect the remote and explain whether a button pad, casing, battery or different repair is likely to address the symptom. Ask about the functions that will be tested after work. Travokeys provides rubber button and casing replacement for supported remotes in Benoni." },
    { heading: "What to tell a locksmith", body: "Share the vehicle make, model and year, and describe which remote functions fail. Say whether the key still starts the engine, whether you have a spare, and whether the issue began after a specific event. If the remote has been opened before or uses an aftermarket casing, mention that too. The remote’s appearance or part number can sometimes help, but photographs should not be sent to a contact you have not verified. Ask whether the service is a battery replacement, inspection, button repair or a new remote, and what is included in the price. A clear scope avoids confusion between a simple battery service and a more involved programming job." },
    { heading: "Check the repair before leaving", body: "After any repair, test the remote at a sensible distance and confirm the functions that were agreed. If range remains poor, explain the result to the technician rather than assuming that a new battery has failed. If the remote works only in one location, note that pattern because environmental interference can be relevant. Keep the key dry, avoid crushing it in a pocket or bag, and replace a damaged casing before the board is exposed. If the vehicle still does not respond, the issue may require diagnosis beyond the remote itself. A good repair conversation should distinguish what has been confirmed from what remains uncertain." },
  ],
  "car-key-casing-damage": [
    { heading: "Why the outer shell matters", body: "The casing protects the key blade, buttons and electronic components from everyday wear. A cracked or loose shell can allow dirt and moisture to reach the internals, and a broken hinge or key ring loop can make the key easier to lose. Damage may begin as cosmetic wear but become more serious when the case no longer closes securely. Inspect the key for separated seams, missing pieces, buttons that sit unevenly or a blade that wobbles. If any electronics are exposed, minimise further handling and arrange an assessment. A replacement shell can be a practical fix when the internals remain functional, but it is not a universal solution for every broken key." },
    { heading: "Casing replacement is not the same as a new key", body: "A casing replacement changes the outer housing. Depending on the key design, reusable internal components may be moved from the damaged shell into a compatible replacement. The blade may also need to be transferred or replaced, and the correct button pad must align with the electronic board. If the circuit board, transponder or blade is damaged, a new shell alone may not restore operation. Some designs are sealed or difficult to transfer without risk, so a technician should inspect the key before promising a casing repair. Ask what parts will be reused, what will be replaced and whether programming is expected. Clear answers help you understand the difference between a shell repair and a complete replacement key." },
    { heading: "Match the shell to the exact key", body: "Aftermarket casings may look very similar while having different internal supports, button positions or blade arrangements. A close but incorrect fit can leave a button pressed continuously, prevent the case from closing, or expose the board to movement. The correct replacement depends on the key style and sometimes the vehicle’s model year or specification. Do not buy a generic shell solely because its outside shape looks right in a photograph. If you contact a locksmith, describe the vehicle and show the key only through an appropriate, trusted channel. The technician can check whether a suitable shell and button layout are available before proceeding." },
    { heading: "Protect the electronics during the repair", body: "Opening a damaged key without the right tools can crack retaining clips, tear a battery contact or harm the circuit board. Glue is especially risky: it can spread into the button mechanism, prevent future opening and make a proper repair harder. If a small piece has broken away, keep it and bring it with the key because it may help identify the casing. Avoid exposing the internals to water, dust or static-prone materials. A locksmith should handle the transfer carefully and confirm that the board, battery and any transponder remain in the correct position. The repair should be tested before the key is returned." },
    { heading: "Know when the casing is not enough", body: "A key that no longer starts the car, a remote with multiple dead buttons or a key that has been crushed may have internal damage beyond its shell. If the blade itself is bent or broken, a casing change does not correct the cut. If the vehicle has intermittent recognition issues, the cause may be unrelated to the housing. Explain all symptoms before the repair and ask whether any additional inspection is recommended. A technician should distinguish confirmed damage from possible faults, then seek approval before expanding the work. This avoids paying for a cosmetic repair when the underlying problem needs a different solution." },
    { heading: "Aftercare for a replacement case", body: "Once the new shell is fitted, check that all buttons move freely and return to their normal position. Confirm that the key blade sits firmly and that the case stays closed without gaps. Test remote functions and engine starting where applicable, following the vehicle’s normal procedure. Keep the key away from liquids and do not use the blade or key ring as a lever. If the casing opens again or a button becomes difficult to press, contact the provider promptly and describe what has changed. Travokeys can assess casing replacement for supported vehicle keys in Benoni; call with your vehicle and key details before arranging service." },
  ],
  "rubber-button-wear": [
    { heading: "How button wear affects everyday use", body: "Car remote buttons are pressed many times over the life of a vehicle. The rubber pad can soften, split or lose its raised symbols, making it harder to feel which function you are pressing. A missing cover also leaves the key’s internal buttons and circuit board more exposed to dirt, moisture and accidental pressure. If a button sticks down or requires excessive force, stop pressing it repeatedly; that can strain the small switch underneath. Note which buttons are affected and whether the remote still operates the vehicle. Those observations help a locksmith decide whether a replacement rubber pad, casing or a broader repair should be considered." },
    { heading: "A worn pad and a failed switch are different issues", body: "The visible rubber pad transfers pressure from your finger to a small switch on the remote’s circuit board. Replacing the pad can help when the rubber is the worn component, but it will not repair a switch that is physically damaged or a circuit board fault. Similarly, a remote that has stopped responding entirely may have a battery, contact, programming or vehicle-side issue. A proper inspection distinguishes the outside symptom from the underlying cause. Ask the technician to explain whether the button pad is the suspected problem and what will be tested after replacement. This avoids assuming that every unresponsive button needs the same repair." },
    { heading: "Fit and button layout must match", body: "Remote casings and rubber pads are designed around a particular shape, board and button arrangement. Even a small mismatch can leave buttons off-centre, pressed continuously or difficult to activate. Some remotes have different layouts for the same vehicle family, so identify the actual key rather than relying on the badge or model name alone. The circuit board must also sit securely inside its shell. A compatible replacement should allow each button to move freely and return without sticking. If the key has been modified or previously repaired, tell the locksmith before work begins because that can affect the available parts and fit." },
    { heading: "Keep a damaged remote protected", body: "If part of the rubber cover has fallen away, keep the key dry and avoid storing it loose with coins or other objects that can press the exposed switches. Do not cover it with adhesive tape that leaves residue over the buttons, and do not apply glue around the opening. Those fixes may make the remote harder to open and can interfere with the switch or board. If the casing is cracked as well, ask whether replacing the complete shell is more practical than replacing only the pad. Bring any loose pieces to the appointment, as they may help identify the correct design." },
    { heading: "Describe the symptom before requesting a repair", body: "When calling, mention the vehicle make, model and year, which button or buttons are worn, and whether the remote still locks or unlocks the car. Explain if the key still starts the engine, has been dropped or has had liquid exposure. A photo may help identify the shell if it is sent to a verified service contact, but it cannot establish the remote’s internal condition. Ask what the inspection and replacement include, and whether any programming is expected. Travokeys offers rubber button replacement for supported remotes in Benoni; suitability is confirmed after identifying the key type." },
    { heading: "Test and care for the repaired remote", body: "After the new pad is fitted, press each button gently and check that it moves smoothly, sits level and returns to its original position. Test the remote functions that were agreed, and mention any button that remains intermittent. Keep the key away from water and avoid leaving it under heavy objects. If a problem returns, describe when it happens and whether the key still starts the vehicle. A repaired button pad is a maintenance solution for the casing interface; it does not correct every possible electronic fault. Regularly checking the key can help you notice wear before a button becomes unusable." },
  ],
  "remote-battery-symptoms": [
    { heading: "Recognise patterns that may indicate a weak battery", body: "A remote battery that is nearing the end of its life may produce reduced range, delayed response or intermittent operation. Some remotes provide a dashboard warning, but not every vehicle does. You might notice that the remote works only when held near the vehicle or that it takes several presses to lock the doors. These signs are useful but not conclusive: worn buttons, damaged contacts, interference or a vehicle receiver problem can look similar. Note when the symptoms started and whether they occur in different locations. If another authorised remote is available, comparing its behaviour may provide helpful context for a technician." },
    { heading: "Check the correct battery type", body: "Remote keys use different battery sizes and chemistries, and the correct type depends on the design. Check the owner’s manual or ask a qualified provider rather than choosing a battery based only on its appearance. A battery with the wrong thickness or orientation may not make proper contact, even if it fits inside the shell. If you open the key, avoid touching or bending delicate contacts and keep the old battery away from children and pets. Small button batteries can be dangerous if swallowed. If the case is sealed or difficult to open, professional replacement can reduce the chance of cracking the housing or damaging the board." },
    { heading: "Battery replacement should include a fit check", body: "The positive and negative sides must face the correct direction, and the battery needs to sit securely against the contacts. A loose contact or residue can cause the same intermittent behaviour as a flat battery. Once fitted, the casing should close fully without pinching buttons or leaving a gap that admits moisture. The remote should then be checked for its normal functions. Some vehicles may require an owner-manual procedure if a remote has lost synchronisation, but that is different from replacing the battery and is model-specific. If the key does not respond after replacement, avoid repeated disassembly and ask for further inspection." },
    { heading: "When a new battery does not solve it", body: "If the remote remains unresponsive with a suitable fresh battery, several possibilities remain. The contacts may be corroded, the rubber buttons worn, the circuit board damaged, or the vehicle’s receiver may not be responding. A key that has been dropped or exposed to liquid deserves careful inspection. Check whether other remote functions or another key work, then tell the locksmith exactly what you observed. Do not assume the replacement battery is defective without checking its specification and installation. A technician can assess the remote and vehicle context and explain whether a button repair, casing replacement, diagnosis or a different solution is more appropriate." },
    { heading: "Handle small batteries safely", body: "Button batteries are small and can cause serious harm if swallowed, particularly by children. Store new and used cells securely, keep them in their packaging until needed, and dispose of used batteries through an appropriate collection point where available. Do not leave an open remote or loose cell on a table or inside a vehicle where a child could reach it. Avoid shorting the battery terminals with metal tools. If a battery is swallowed or suspected to have been swallowed, seek urgent medical assistance. This safety step matters even when the key repair itself is minor." },
    { heading: "Prevent a flat remote from becoming an access problem", body: "If your vehicle depends on a remote for access or starting, follow the owner’s manual about its backup method and keep the physical key blade available where applicable. Replace a battery when clear symptoms appear rather than waiting until the remote stops completely. A spare remote can offer another option, but it should be stored securely and tested occasionally. Travokeys provides remote battery replacement for supported key types in Benoni. Call with the vehicle and remote details to check suitability, and ask whether the service includes inspection if your remote has already become unreliable." },
  ],
  "car-key-not-starting-car": [
    { heading: "Record what happens when you try to start", body: "A useful first step is to describe the exact behaviour rather than simply saying that the car will not start. Does the engine turn over, click, or remain silent? Does the dashboard show a key symbol, security light or message? Can you turn the key normally, and do the remote buttons still work? These observations help a technician decide which systems may need checking, but they do not identify the fault on their own. If the vehicle behaves differently with a spare key, mention that too. Avoid repeated attempts if the car produces unusual noises or warning messages, and keep the vehicle in a safe location while you arrange help." },
    { heading: "Consider the immobiliser without assuming it is the cause", body: "Many vehicles use an immobiliser that needs to recognise a coded key before permitting the engine to start. A transponder key problem is one possibility when the vehicle reports that the key is not recognised, but similar symptoms can arise from low vehicle battery voltage, wiring, a receiver or another electronic fault. A key may also turn mechanically while its transponder is not accepted. The dashboard light pattern and owner’s manual can provide useful context, but model-specific meanings differ. Share what the vehicle displays and when it happens. Do not attempt to bypass the immobiliser; that can damage security systems and may create safety or legal concerns." },
    { heading: "Compare with a spare key carefully", body: "If you have another authorised key, trying it once in a safe setting may help you describe whether the problem seems limited to one key. If the spare works normally, the primary key may need inspection, but this does not prove the cause. If neither key works, a vehicle-side issue becomes another consideration. Note whether the remote functions behave differently from the starting function. Some key designs use separate components for remote locking and engine authorisation. Keep a record of what you tested, and do not continue if the vehicle’s manual warns against repeated attempts or if unusual electrical symptoms appear." },
    { heading: "Mechanical and electrical symptoms can overlap", body: "A key that is difficult to turn may indicate wear in the key blade or a mechanical ignition or lock issue. A key that turns normally but fails to start may involve a different set of possibilities. Other common causes of a no-start condition include the vehicle battery, starter circuit, fuel system or engine management. It is easy to focus on the key because it is the part in your hand, but the vehicle needs a broader assessment when symptoms point beyond it. Explain whether the problem began suddenly, after a repair or after the key was dropped. A qualified technician can decide whether key work or general vehicle diagnostics should come first." },
    { heading: "What diagnosis can establish", body: "A scan tool may retrieve fault information from vehicle systems, and additional checks may be needed to interpret it. A code related to key recognition does not automatically mean that a new key is required. A technician may need to assess the key, immobiliser communication, vehicle voltage and related components. Ask which checks were completed and what evidence supports the recommendation. If the proposed work changes after diagnosis, request a revised scope and price before authorising it. Travokeys offers vehicle diagnostics and key services for supported vehicles in Benoni; share the model, year, dashboard messages and symptoms when you call." },
    { heading: "Prepare for professional assistance", body: "Have the vehicle make, model, year and location ready. Tell the provider whether a spare key exists, what the dashboard shows and whether the engine turns over. If the vehicle is in a garage or restricted location, explain access arrangements. Gather any documents that may be required to establish authority for key work. Ask whether the provider can assess both the key and the vehicle or whether another specialist may be appropriate. Do not buy a replacement key based only on a warning light before the fault is understood. A clear conversation can help direct you to the right type of assistance and avoid unnecessary parts." },
  ],
  "ecu-cloning-explained": [
    { heading: "What an ECU does", body: "An engine control unit is an electronic module that manages or coordinates engine functions. Vehicles may also rely on other control units for body systems, transmission, security or communications. The term ECU is sometimes used broadly, so identifying the exact module matters before discussing repair or replacement. A fault code or starting problem does not prove that the engine ECU has failed. Wiring, power supply, sensors, communications or another module can produce related symptoms. Proper diagnosis should establish which unit is involved and whether replacement is actually needed. Ask the technician to explain the evidence before authorising a costly module change." },
    { heading: "What cloning generally means", body: "ECU cloning typically refers to transferring relevant electronic data from an original control unit to a compatible replacement. The purpose is to help the replacement work with the vehicle’s configuration, but the exact data and process vary by vehicle and module. Cloning may be considered when an original unit has a fault and usable information can still be accessed. It is not the same as repairing the original module, and it is not a universal method for every vehicle. Some systems may require different programming, configuration or manufacturer procedures. A provider should identify the module and explain the proposed method in clear terms." },
    { heading: "Compatibility and original data are critical", body: "The replacement unit generally needs to be compatible with the vehicle and the original module’s part number, hardware and software arrangement. Differences that look minor can prevent communication or correct operation. If the original unit is completely inaccessible or severely damaged, the data needed for a clone may not be available. Prior modifications, replacement modules or an immobiliser fault can complicate the assessment. Before proceeding, ask what compatibility checks will be made and what happens if cloning is not possible. A technician should not promise success without identifying the module and condition. Provide the vehicle details and any part numbers you can safely obtain." },
    { heading: "Diagnosis should come before cloning", body: "A vehicle may show symptoms such as no-start, warning lights or communication faults for reasons unrelated to a failed ECU. Replacing or cloning a module without confirming the cause can leave the underlying problem unresolved. A diagnostic process may include checking power and ground, communications, related sensors and fault history. The appropriate checks depend on the vehicle and symptoms. Ask for a clear description of the findings and why an ECU solution is recommended. If another fault is found, request an explanation of how it affects the plan and any additional cost before authorising work." },
    { heading: "Security, authorisation and data handling", body: "Control units can contain vehicle-specific information and be connected to immobiliser or anti-theft functions. A responsible provider may verify that you are authorised to request work and may ask for vehicle documentation. Provide only the information necessary for the assessment, and ask how any original module or data will be handled. If a used replacement unit is being considered, confirm its suitability and whether it has prior configuration that could affect the job. Do not attempt to alter security data using unofficial files or bypass tools. These systems are vehicle-specific and security-sensitive." },
    { heading: "Questions to ask before approving ECU work", body: "Ask which module has been identified, what diagnostic evidence points to it, and whether the original unit has been tested. Confirm the replacement part, compatibility checks, proposed cloning or programming method, scope of testing and quoted price. Ask what the fallback options are if the original data cannot be read or the replacement is incompatible. Make sure the quote distinguishes diagnostic work from module work and any parts or call-out charges. Travokeys assesses ECU cloning requests for supported vehicles in Benoni. Call with the make, model, year and ECU details so the team can discuss whether an assessment is appropriate." },
  ],
  "vehicle-diagnostic-codes": [
    { heading: "What a diagnostic trouble code represents", body: "Modern vehicles monitor many systems and can store diagnostic trouble codes when a reading or condition falls outside an expected range. A code usually points to a circuit, system or condition for further investigation. It does not always name the failed part. For example, a sensor-related code might be caused by the sensor, wiring, a connector, a supply voltage issue or another condition that affects the reading. The code is evidence, not a complete diagnosis. A technician interprets it alongside the vehicle’s symptoms, service history and other checks. This distinction helps prevent replacing parts simply because their name appears in a scan result." },
    { heading: "Why the same code can have different causes", body: "A vehicle system is made up of interacting parts. A fault in one area can influence readings elsewhere, and different vehicles may use similar code labels for systems with different designs. A loose connector, damaged wire, intermittent sensor or low voltage may create a code that appears to identify a component. The same code can also return after a repair if the original cause was not addressed. This is why the exact vehicle make, model, year and system matter. Ask the technician what checks were used to narrow down the cause and whether the fault was active, stored or intermittent." },
    { heading: "A useful diagnostic process", body: "A technician may begin by recording the vehicle information and reported symptoms, then scanning the relevant control units. They may review freeze-frame or live data where available and carry out additional checks such as inspecting connectors, power, ground or system operation. The procedure depends on the fault and the equipment supported by the vehicle. Some faults need physical testing beyond a scan. After a repair, the technician may clear codes and confirm whether the issue returns, but clearing a code alone is not a repair. Ask what was checked, what was found and how the conclusion was reached." },
    { heading: "Warning lights and urgency", body: "Not every warning light signals the same level of risk. Consult the owner’s manual for the meaning of the specific warning and follow its safety advice. If the vehicle is overheating, losing braking performance, showing an oil-pressure warning or behaving dangerously, stop when safe and arrange appropriate assistance rather than continuing to drive. A diagnostic code can help identify a system that needs attention, but it does not replace an immediate safety decision. Note whether the light is steady or flashing and whether the vehicle’s performance has changed. Share that information when arranging an assessment." },
    { heading: "Questions to ask about the results", body: "Ask for the code description, the system in which it was recorded and the technician’s interpretation. Find out whether the code was current or historical, what supporting tests were performed and which findings rule out other likely causes. Request an explanation of the recommended repair and whether a second diagnostic step is necessary. If parts are recommended, ask why each one is needed and whether the repair will be tested afterward. You should be able to understand the proposed scope before approving it. If the evidence is uncertain, it is reasonable to ask what remains unknown and what further checks would clarify the result." },
    { heading: "Prepare your vehicle details", body: "Before calling, write down the vehicle make, model and year, along with the dashboard warnings and symptoms. Note when they occur, whether they are constant or intermittent and any recent repairs, battery replacement or modifications. Bring or describe prior scan results if available, but do not rely on an old code list as a confirmed diagnosis. Travokeys offers diagnostics across vehicle makes, with coverage depending on the model, system and fault. Call to confirm whether your particular vehicle can be assessed and what information to bring." },
  ],
  "immobiliser-warning-light": [
    { heading: "Check the vehicle’s own guidance", body: "Immobiliser indicators differ between manufacturers. On some vehicles, a security light flashes when the car is parked and changes when a recognised key is used; on others, the same symbol may signal a fault if it remains on or appears with a message. Look up the indicator in the owner’s manual for your exact model and note the pattern. Do not assume that another driver’s description applies to your car. If a warning appears with a no-start condition, record whether the engine turns over and whether the remote still works. This context helps a technician understand what the vehicle is reporting." },
    { heading: "Compare the key symptoms", body: "If you have another authorised key, you may check whether it produces the same warning, following the vehicle’s normal starting procedure. If one key works and another does not, the affected key may need inspection, but the comparison does not prove that the transponder is the only cause. If neither works, there may be a vehicle-side system issue or another condition. Remote locking and engine authorisation can be separate functions, so a remote that locks the doors may still not start the car. Describe those differences instead of saying only that the key has stopped working." },
    { heading: "Possible causes need proper assessment", body: "A warning can be related to a key that is not recognised, a weak vehicle battery, an immobiliser communication issue, a damaged key or a module fault. Wiring, aftermarket alarms and previous repairs can also affect the system. The exact possibilities depend on the model and symptom pattern. A dashboard icon alone is not enough to order a new key or module. A qualified technician may need to inspect the key and scan the vehicle to identify the cause. Ask what evidence supports any recommendation and whether the issue has been reproduced during testing." },
    { heading: "Avoid bypass or reset advice from generic sources", body: "Online instructions sometimes suggest bypassing or disabling an immobiliser. These systems protect vehicles from unauthorised use, and an incorrect procedure can damage modules, create further faults or compromise security. Do not short wires or install unverified devices based on a video or forum post. If a manufacturer-approved owner procedure is listed in your manual, follow it exactly and only for your specific model. If the warning continues, get professional help. A provider may ask for proof that you are authorised to request work because immobiliser and key programming tasks affect vehicle security." },
    { heading: "What to share when booking", body: "Tell the locksmith the vehicle make, model, year, the exact warning or dashboard message and whether the engine turns over. Say whether a spare key is available and whether its behaviour differs. Mention recent battery changes, electrical work, water exposure or key damage. If the vehicle is parked in a restricted area, explain how the technician can access it. Ask whether the provider can assess both the key and vehicle system or whether another specialist may be needed. These details allow a more useful conversation without promising a diagnosis before inspection." },
    { heading: "After an immobiliser repair", body: "Once a repair or key service is completed, confirm that the vehicle starts reliably with the authorised keys and that any agreed remote functions operate. Ask whether any stored warnings remain and what they mean. If the symptom returns, note the conditions and contact the provider with that information. Keep the spare key secure and avoid leaving all keys in one place. Travokeys provides automotive key and diagnostic assistance for supported vehicles in Benoni. Call with your vehicle details to check coverage and discuss a next step." },
  ],
  "what-to-share-locksmith": [
    { heading: "Identify the vehicle clearly", body: "Start with the vehicle’s make, model and year. If you know the trim, engine or market specification, include it, because systems can vary between versions. The registration or VIN may help a provider identify a vehicle, but do not post it publicly or send it to an unverified contact. Describe the key type if you can: a standard blade, remote-head key, proximity fob or push-button start. If you are not sure, say so rather than guessing. A locksmith can ask follow-up questions or explain what information is useful for the particular service." },
    { heading: "Explain the problem in observable terms", body: "Describe what happened and what the vehicle does now. Is the key missing, physically broken, difficult to turn, or not recognised? Do remote buttons work? Does the engine turn over? Is there a dashboard message or warning light? Mention if the issue is constant or happens intermittently. Avoid diagnosing the fault yourself; a clear description helps the technician consider possible causes without anchoring on an assumption. If the key was dropped, became wet, or recently had a battery changed, include that detail. These observations can help determine whether the call concerns key cutting, coding, remote repair or vehicle diagnostics." },
    { heading: "Share your location and access constraints", body: "Give the address or a clear location description and explain where the vehicle is parked. Mention a gate, underground car park, security desk, restricted operating hours or any access instructions. If the vehicle is in a risky location or blocks access, say so early. Do not leave the car unsecured while waiting. Travokeys is based at Silver Pines Estate, 29 North Rd, Crystal Park, Benoni, but the service arrangement and availability should be confirmed by phone. Providing your location helps the business discuss whether it can assist and what timing is realistic." },
    { heading: "Mention keys, previous work and authorisation", body: "Tell the locksmith whether you have a working key, a spare or no keys at all. Explain any previous key replacement, ECU work, alarm installation or electrical repair that may relate to the symptom. You may be asked to confirm that you own the vehicle or have permission to arrange the service. Ask which documents are appropriate and prepare them if available. If the owner is not present, explain who will authorise the work and how they can be contacted. These checks help protect vehicle owners and can prevent the appointment from being delayed." },
    { heading: "Ask about scope, price and availability", body: "Before confirming a booking, ask whether the locksmith supports the vehicle and the specific work you need. Clarify the estimated price, any call-out or travel charges, what parts and functions are included, and how the finished work will be tested. Ask what happens if inspection shows a different fault or the required part is unavailable. A phone estimate may change after the vehicle is identified, but the business should explain the change and seek agreement before doing additional work. Avoid relying on an exact promise where the vehicle and key have not been assessed." },
    { heading: "Use a safe, verified contact", body: "Confirm the business name and contact number before sending vehicle documents or sensitive details. Do not share security codes, passwords or unnecessary personal information. If a provider asks for documents, ask why they are needed and how they will be handled. Keep the vehicle accessible and wait somewhere safe. For urgent roadside situations, follow local safety advice and consider contacting the relevant property or road authority. A concise, accurate call helps the locksmith respond appropriately and helps you decide whether the proposed service fits your situation." },
  ],
  "proof-of-ownership-car-key": [
    { heading: "Why authorisation matters for vehicle key work", body: "A new key or programmed remote can provide access to and use of a vehicle. A locksmith therefore has a responsibility to avoid assisting someone who is not authorised to request the work. Asking for proof is a security measure, not an accusation. It helps protect owners, fleet operators and other authorised users. The exact verification process depends on the circumstances and the provider’s policies. A technician may need to see identification, vehicle paperwork or confirmation from the registered owner. Ask what is required before the appointment so you can prepare and avoid unnecessary delay." },
    { heading: "Examples of situations that need explanation", body: "A vehicle may belong to a spouse, parent, employer, rental company or customer rather than the person calling. You may be helping an owner who is travelling, or a company vehicle may be managed by a fleet administrator. Explain the relationship and who can authorise the work. If the owner cannot be present, ask the service provider what confirmation they will accept. A document showing a vehicle registration may not alone establish that you are entitled to request a key, and an identity document alone may not establish a connection to the car. The provider should explain its requirements without asking for information that is not reasonably needed." },
    { heading: "Share documents carefully", body: "Prepare documents for inspection if requested, but use a verified contact channel and ask whether a copy is necessary. Avoid sending full identity or vehicle documents through a public social media comment or to an unknown number. If you do send a copy, consider whether information not needed for verification can be obscured, provided the provider accepts that format. Do not provide account passwords, one-time security codes or unrelated personal records. A legitimate provider should be able to explain what information it needs and why. If you are uncertain about a request, contact the business using a phone number you obtained independently." },
    { heading: "If documents are locked inside the vehicle", body: "It can happen that the paperwork needed to verify a vehicle is inside a locked car. Tell the locksmith this before arranging the job. They may be able to explain another way to confirm authority, such as contacting the registered owner or checking alternative information. Do not assume that a technician can proceed without verification, and do not ask them to bypass their security process. If the vehicle belongs to someone else, make sure the owner can be reached. Early notice gives both sides a chance to agree on an acceptable verification method before work begins." },
    { heading: "Fleet and business vehicles", body: "For a company vehicle, the person requesting work may need to show that they are authorised by the fleet owner or employer. Have the fleet contact or manager’s details ready if appropriate, and explain whether the vehicle is assigned to you or shared. If there is a formal work-order or procurement process, follow it before the appointment. The provider may need to record who approved the key or module work. These steps help prevent unauthorised duplication and make clear who is responsible for approving charges. Do not share confidential fleet information beyond what is needed to confirm the request." },
    { heading: "What a responsible verification process looks like", body: "A responsible process is proportionate: it confirms the caller’s authority while minimising unnecessary collection of personal information. The technician should explain what evidence is required, how it will be used and whether a copy will be retained. If the request cannot be verified, the provider may decline or pause the work. This protects both the vehicle owner and the locksmith. Travokeys may confirm authorisation details before key, lock, coding or ECU work. Ask any questions before the technician begins so you understand what is required and what information will be recorded." },
  ],
  "when-to-replace-car-key": [
    { heading: "Separate visible damage from functional faults", body: "Start by identifying what has actually changed. A cracked shell, missing button cover, loose blade or intermittent remote response are different symptoms and may call for different work. Note whether the key still starts the vehicle, whether all buttons work and whether the damage followed a drop or exposure to water. A key can look worn while its electronics remain functional, and a key that looks fine can still have an internal fault. Describe the symptoms rather than requesting a particular part before inspection. That helps the technician consider whether a casing, button pad, battery, blade or complete replacement should be assessed." },
    { heading: "When a casing or button repair may be suitable", body: "A casing or rubber button replacement may be practical when the outer shell or pad is worn but the electronic board and other reusable components are in working condition. The correct replacement must match the key design and position the buttons accurately. If the board is damaged or the casing cannot be opened safely, a new key or different repair may be more appropriate. Ask the locksmith to explain what will be transferred and what will be replaced. After the repair, confirm the case closes securely, buttons move freely and the agreed functions work. A casing repair does not automatically include a new blade or programming." },
    { heading: "When a battery change is worth considering", body: "A remote battery may be worth checking if range has reduced, buttons respond intermittently or the vehicle shows a low-key-battery warning. These symptoms can have other causes, so confirm the correct battery type and fit. If a fresh suitable battery does not help, avoid buying several more without diagnosis. Damaged contacts, worn buttons, circuit faults or vehicle-side problems may remain. A provider can inspect the remote and advise whether the next step should be battery service, repair or further assessment. Small button batteries need careful handling and safe storage away from children." },
    { heading: "When complete key replacement may be needed", body: "A new key may be necessary when the blade is lost or unusable, the electronic components are damaged beyond repair, or no compatible casing or part is available. Replacing the key may require cutting, coding or pairing with the vehicle, depending on the system. If all keys are missing, the process can differ from making a spare from a working key. Ask what functions are included and how the new key will be tested. Confirm whether old keys need to be removed from the vehicle’s accepted-key list if security is a concern. The options vary by vehicle and must be confirmed for the specific model." },
    { heading: "Avoid repairs that make later service harder", body: "Glue, unsuitable batteries and forced openings can turn a repairable key into a more complicated job. Avoid prying the shell with a sharp metal tool, scraping the circuit board or applying adhesive near buttons. If the key is wet, do not heat it or continue pressing the switches; explain the exposure to the technician. Keep loose pieces in a small bag and bring them to the appointment. A professional inspection can establish whether the internal parts remain reusable and whether the planned repair is likely to address the problem." },
    { heading: "Compare the options before deciding", body: "Ask the technician to compare the proposed repair with a full replacement in terms of scope, parts, compatibility and testing. Clarify the expected charge, any call-out fee and what happens if a repair does not restore the key. A lower-cost shell change is not a good value if the actual fault lies in electronics, while a full replacement may be unnecessary if only a rubber pad is worn. A clear explanation allows you to make an informed choice. Travokeys can assess supported key and remote issues in Benoni; call with your vehicle details and a description of the symptoms." },
  ],
  "mobile-auto-locksmith-benoni": [
    { heading: "Confirm the service fits your vehicle and problem", body: "Automotive locksmiths do not all support the same vehicles or perform the same work. Before arranging an appointment, explain whether you need key cutting, coding, a remote repair, casing replacement or diagnostics. Provide the make, model and year, and say whether a working key remains. Ask directly whether that vehicle and service are within the provider’s capabilities. Some jobs depend on specialist parts, access to the vehicle or information from a particular module. A directory listing or general claim that a locksmith works on cars is not proof that a specific vehicle is supported. Clear confirmation protects your time and helps set expectations." },
    { heading: "Understand location and attendance arrangements", body: "If you expect a locksmith to come to the vehicle, confirm that the provider offers service at your location and ask about any travel or call-out charge. Share the address, parking conditions, access restrictions and a safe point to meet. Do not assume that a business’s physical address means it provides mobile service everywhere. Travokeys is based at Silver Pines Estate, 29 North Rd, Crystal Park, Benoni; call to confirm where assistance is available and the current arrangement. If your car is in a controlled parking area, speak with security about access rules before the technician arrives." },
    { heading: "Ask for clear pricing information", body: "Before confirming, ask what the quoted amount covers: labour, key or remote, cutting, coding, travel, call-out, diagnostics and any additional testing. If a phone estimate is provisional because the vehicle has not been identified, ask what could change it. The provider should explain a revised scope and seek your approval before proceeding with additional work. Be cautious of unusually low headline prices that omit important charges or rely on assumptions about a different key type. Keep a note of the estimate and the agreed work so you can compare it with the final invoice." },
    { heading: "Check credentials and protect the vehicle", body: "Use a business whose identity and contact details you can verify. Ask what proof of authorisation is needed and have the relevant vehicle information ready. A responsible locksmith may refuse to cut or program a key until authority is established; that is a security safeguard. Do not post your VIN, registration, address or photographs of security components publicly. If the car is in an unsafe place, prioritise your personal safety and follow local road or property guidance while arranging help. Confirm how the technician will identify themselves when they arrive and where you should meet." },
    { heading: "Set a realistic expectation for timing", body: "Arrival and completion times depend on the provider’s workload, distance, traffic, vehicle access and whether a compatible part is available. Ask for the best current estimate and how you will be updated if circumstances change. Avoid treating an estimated time as a guarantee unless the business explicitly confirms it. If the vehicle is blocking access or parked in a restricted location, explain the urgency during the call. Keep your phone available and ensure the technician can reach you. A clear update process is especially useful when the key or vehicle needs assessment before the exact work can be determined." },
    { heading: "Prepare before you call", body: "Write down the vehicle details, location, key symptoms and whether another key is available. Gather proof that you are authorised to request the work and ask what documentation is acceptable. Note any recent repairs, aftermarket alarms or security equipment. Travokeys is open 24 hours according to the business information supplied; phone 073 702 4949 to confirm present availability, service coverage and charges. The call is also a good time to explain the issue and ask what the technician will need when assessing the vehicle." },
  ],
  "car-key-remote-range": [
    { heading: "Notice whether the range change is consistent", body: "A remote that once worked from several metres away but now responds only close to the vehicle may have a weakening battery. Before drawing a conclusion, note whether the reduced range occurs every time or only in certain locations. Try the normal operating distance in a safe, open area and compare with a spare remote if available. Do not repeatedly press the buttons from far away, as that can make it harder to tell whether the vehicle received the signal. A consistent change is useful information for a technician, but it is not proof of a particular fault. Record when the behaviour started and any event that came before it." },
    { heading: "Battery condition and correct replacement", body: "A low remote battery can reduce signal strength or make response intermittent. The correct battery depends on the fob design; selecting a similar-looking cell may result in poor contact or improper fit. Follow the vehicle maker’s guidance or ask a locksmith to check the key type. Ensure the battery is installed in the right orientation and the casing closes fully. If replacing it does not restore range, the issue may involve worn contacts, a damaged circuit, buttons or a receiver. Avoid repeatedly opening the remote or bending the battery contacts, because the key can be damaged further." },
    { heading: "Environmental interference can matter", body: "Radio-frequency devices and local conditions can sometimes interfere with a remote signal. If the remote works normally in one location but not another, mention that pattern. Try moving a short distance only if it is safe and permitted, and compare the result without changing several variables at once. Interference may be temporary and does not necessarily mean the remote has failed. If several vehicles or remotes are affected in the same place, that observation may be useful. Do not assume interference is the explanation if the remote has also been dropped or behaves poorly everywhere; the key may still need inspection." },
    { heading: "Compare the spare and the vehicle response", body: "If a second authorised remote is available, compare its range from the same position and under similar conditions. If both remotes have reduced range, the vehicle receiver, its power or environmental factors may deserve consideration. If only one key is affected, the remote itself becomes a stronger possibility, although a professional assessment is still needed. Check whether the physical key blade and engine-start function remain normal; these may use separate functions from remote locking. Describe each difference to the locksmith. A comparison does not require dismantling the key or attempting an electronic reset." },
    { heading: "Inspect the casing and buttons", body: "A cracked shell, loose battery cover or worn button pad may affect contact or expose the board to damage. Look for visible gaps, corrosion or buttons that remain pressed, but do not pry open a sealed remote. If the key has been exposed to water, tell the technician even if it now appears dry. A casing or rubber button replacement may help when the outer components are worn and internal electronics remain usable. If the signal circuit is damaged, a casing repair alone will not restore range. Ask what was inspected and what functions will be tested." },
    { heading: "When to arrange further assessment", body: "If the range continues to deteriorate, the remote stops responding, or a new battery changes nothing, seek an assessment instead of continuing to replace parts. Share the vehicle make, model, year, remote type and comparison with any spare. Ask whether the service covers remote inspection, battery replacement and vehicle-side diagnostics. Travokeys can inspect supported remotes and advise Benoni drivers about the next step. Phone before visiting to confirm availability and whether the specific key type can be handled." },
  ],
  "diagnostic-scan-before-repair": [
    { heading: "A scan is the start of an investigation", body: "A diagnostic scan communicates with vehicle systems and retrieves available fault information. It can help a technician understand what the vehicle has recorded, but it cannot see every mechanical issue or confirm that a named part has failed. Some faults do not store a code, and some stored codes relate to an earlier event that is no longer present. The scan is most useful when paired with a clear description of symptoms, appropriate testing and knowledge of the vehicle. Treat it as a tool that guides the next question, not a substitute for diagnosis." },
    { heading: "Match the code to the actual symptom", body: "The same vehicle may have several stored codes, and not all of them will relate to the concern you brought in. The technician should consider when each code appeared, whether it is current and whether the symptoms match. For example, a warning light and a starting problem may be connected or may be separate issues. A thoughtful assessment prioritises safety and the customer’s reported concern, then checks the supporting evidence. Ask which code or finding is relevant to your complaint and why. This makes it easier to understand the relationship between the scan and the proposed work." },
    { heading: "Physical checks can confirm or rule out causes", body: "Once fault information suggests an area to investigate, a technician may inspect connectors, wiring, power supply, ground, fluid levels or component operation as appropriate. The exact checks depend on the vehicle and fault. A poor electrical connection can imitate a failed sensor, and a sensor may be responding correctly to a different underlying problem. Live data and repeat tests may help reveal intermittent behaviour. Ask what physical checks were completed and what they showed. Replacing a part solely because a code mentions it may not address the true cause." },
    { heading: "Clearing a code does not repair a fault", body: "Fault information can sometimes be cleared after a repair or during diagnosis, but deleting a warning does not resolve the condition that caused it. The code may return if the underlying issue remains. A provider should explain whether clearing is part of the test process and how they will confirm the repair afterward. A proper result may include a repeat scan, a road test where suitable or another operating check. Follow any safety instructions in the owner’s manual and do not keep driving if the vehicle shows a serious warning or behaves unsafely." },
    { heading: "Request a useful explanation", body: "Ask the technician to show or describe the diagnostic finding in ordinary language. Find out whether it is active or historical, what symptoms it might explain, and what evidence supports the recommended repair. If the conclusion is uncertain, ask what further test would reduce that uncertainty. Request an estimate for the diagnostic work and a separate estimate for any repair if applicable. You should know what is being authorised before parts are fitted. Clear communication matters as much as the scan itself because it allows you to compare options and make an informed decision." },
    { heading: "Bring context to the appointment", body: "Write down the vehicle make, model, year, warning messages and when the problem happens. Include recent repairs, jump-starts, battery changes or modifications that may be relevant. If you have a previous scan report, bring it, but explain when and where it was produced. Avoid replacing parts beforehand based solely on the report unless a qualified technician has advised you. Travokeys provides diagnostics for supported vehicles in Benoni. Call with your details to check coverage and ask what information would help the initial assessment." },
  ],
  "key-security-after-loss": [
    { heading: "Work out what information may have been lost", body: "The security response can differ depending on whether a key was simply misplaced, stolen, or lost together with documents that identify your vehicle or home. Consider what was attached to the key ring, where it was last seen and whether anyone could connect it to your car. If you suspect theft, tell the relevant authorities and your insurer where appropriate. You may also want to contact property or parking security if the key went missing at a managed site. Sharing the circumstances with the locksmith helps them discuss realistic options for the vehicle’s security system." },
    { heading: "Ask whether the missing key can be de-authorised", body: "Some vehicles support removing a missing key from the list of keys accepted by the security system; others use different procedures or have limitations. The exact option depends on the vehicle’s make, model, year and system configuration. A mechanical blade may still operate a lock even if electronic authorisation changes, depending on the vehicle. Ask a qualified technician to explain what can be changed and what cannot. Do not assume that making a replacement automatically disables every missing key. The technician should confirm the available method before quoting or carrying out a security-related change." },
    { heading: "Balance security with access to the vehicle", body: "If you have a working spare, keep it secure and avoid leaving it inside the car while deciding what to do. If no key remains, a replacement assessment may be needed before any security settings can be changed. Consider where the vehicle is parked and whether there is an immediate risk of unauthorised access. A vehicle dealer or specialist locksmith can explain the supported process; do not attempt an unfamiliar immobiliser reset or bypass. Security work can involve vehicle-specific checks and authorisation. Ask how the replacement will be tested and whether any existing keys will continue to work." },
    { heading: "Use careful information-sharing practices", body: "When arranging assistance, share only what is needed to identify the vehicle and confirm your authority. Avoid posting your location, registration, VIN or key photos publicly. Use a contact number you have independently verified, and ask why any requested document is needed. A responsible provider will explain its verification process and how personal information is handled. If the key was lost with an address tag, mention that without broadcasting the address in a public channel. These steps help you get appropriate service while limiting unnecessary exposure of personal and vehicle information." },
    { heading: "Keep the paperwork and outcome clear", body: "Before security work begins, ask what the proposed change covers, which keys should remain authorised, whether the work affects remote functions and what the price includes. Afterward, confirm the behaviour of each key you still have and ask for a record of the work completed. If the technician cannot confirm that a missing key has been de-authorised, be clear about that limitation and consider additional advice from the vehicle manufacturer or insurer. An accurate record helps if you need to follow up or demonstrate what action was taken." },
    { heading: "Reduce the impact of a future loss", body: "Keep spare keys separate from the vehicle and from documents that reveal where the car is kept. Avoid attaching a home address or registration to the key ring. Store a record of your vehicle details securely so you can provide them when needed, and replace worn keys before they fail. If you use a digital key or tracking service, review its manufacturer-approved security settings. Travokeys can assess key and coding options for supported vehicles in Benoni; phone to explain what happened and confirm which security measures are available for your specific car." },
  ],
  "prepare-for-locksmith-visit": [
    { heading: "Make the vehicle easy and safe to reach", body: "If an appointment is arranged at the vehicle, confirm the exact parking location and whether there are gates, height restrictions, security procedures or visitor rules. Move the vehicle only if it is safe and operable; do not drive it if a serious warning or mechanical issue makes that unsafe. Tell the provider if the car is in an underground garage, on a roadside or in a private complex so access can be planned. Choose a safe place to wait and keep your phone available. Clear access helps the technician assess the vehicle without avoidable delays." },
    { heading: "Gather keys and vehicle information", body: "Bring every key and remote you still have, even if one is damaged or intermittent. Have the make, model, year and, if available, registration or VIN ready. Explain which features do and do not work, and note when the issue began. If there was a recent repair, battery replacement, water exposure or key drop, mention it. These details may help identify the correct key system and prevent the technician from repeating checks you have already described. Store any broken pieces in a bag and bring them along, since they may help establish the key design." },
    { heading: "Prepare authorisation documents", body: "Ask before the visit what proof is needed to show you are authorised to request the work. Have identification and relevant vehicle documents available if requested, but do not send sensitive copies to an unverified contact. If the vehicle belongs to an employer or another person, arrange for the owner or fleet manager to confirm permission if needed. If documents are locked inside the car, tell the provider when booking and ask about an alternative verification method. Resolving this before the technician arrives can prevent the work from being paused at the vehicle." },
    { heading: "Confirm the scope and price", body: "Before work starts, confirm what you asked the technician to do and what the quote includes. Ask about the key or parts, cutting, coding, diagnostic time, travel or call-out fees, and testing. If inspection changes the proposed work, the technician should explain the reason and revised price before proceeding. Ask what happens if a part is unavailable or the vehicle is not supported. Keep a note of the agreed scope. This is particularly useful when an initial phone estimate was based on incomplete information or the key has not yet been inspected." },
    { heading: "During the assessment", body: "Describe the symptoms clearly and allow the technician to inspect the key and vehicle. Do not press buttons or turn the ignition repeatedly while the assessment is underway unless asked. If the technician identifies an additional issue, ask how it relates to your original concern and whether it needs immediate attention. You remain able to ask questions before approving extra work. A useful assessment should distinguish what has been confirmed, what remains uncertain and what the next step would cost. If you are unsure about a recommendation, request a clear explanation before deciding." },
    { heading: "Check the result before the appointment ends", body: "Test the functions included in the agreed work, such as blade operation, engine starting, remote buttons or the diagnostic response. Confirm that the key casing is secure and no buttons stick. Ask whether any limitations remain and what to do if the symptom returns. Keep receipts, service notes and any relevant key information in a safe place. If the vehicle requires a manufacturer procedure afterward, ask for that instruction in writing or refer to the owner’s manual. Travokeys can discuss appointments by phone in Benoni; call ahead to confirm service availability and what to prepare." },
  ],
};
